window.WIB_HOSPITAL_SPEC_CATEGORIES = {
  'Cardiac & Vascular': ['Cardiac','Cardiology','Cardiac Surgery','Cardiac Sciences','Interventional Cardiology','Vascular','Vascular Surgery','Paediatric Cardiac','Heart Transplant'],
  'Cancer & Oncology': ['Oncology','Surgical Oncology','Radiation Oncology','Radiation','Radiation Therapy','BMT','Bone Marrow Transplant','Chemotherapy','Paediatric Oncology','Gynae Oncology','Haematology'],
  'Brain & Spine': ['Neurology','Neurosciences','Neuroscience','Neurosurgery','Spine'],
  'Bones & Joints': ['Orthopedics','Joint Replacement','Sports Medicine','Trauma'],
  'Digestive & Liver': ['Gastroenterology','Hepatology','Liver Transplant','Surgical Gastro'],
  'Kidney & Urology': ['Nephrology','Renal Sciences','Renal Transplant','Kidney Transplant','Urology'],
  'Women & Children': ['Gynaecology','IVF','Maternity','Neonatal','Obstetrics','Fertility','Paediatrics','Paediatric Surgery','Neonatology','PICU'],
  'Eye Care': ['Ophthalmology','Cataract','Retina','Glaucoma','Cornea'],
  'Mental Health': ['Psychiatry','Clinical Psychology'],
  'Transplant & Robotics': ['Transplant','Robotic Surgery','Robotics','Minimal Invasive Surgery','Bariatric Surgery'],
  'General Medicine': ['General Medicine','Surgery','Internal Medicine','General Surgery','General','Critical Care','Emergency','Burns','Diabetology','Dental']
};

// Helper: get the category for a raw specialty string
window.WIB_getHospitalCategory = function(spec){
  for (var cat in window.WIB_HOSPITAL_SPEC_CATEGORIES) {
    if (window.WIB_HOSPITAL_SPEC_CATEGORIES[cat].indexOf(spec) !== -1) return cat;
  }
  return 'Other';
};

// Helper: build a Practo hospital-search URL (real, not Google)
// Practo URL pattern: https://www.practo.com/[city-slug]/hospitals?q=[name]
window.WIB_practoUrl = function(name, city){
  var citySlug = (city||'').toLowerCase().replace(/\s+/g,'-');
  return 'https://www.practo.com/' + encodeURIComponent(citySlug) + '/hospitals?q=' + encodeURIComponent(name||'');
};
